package com.worksphere.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.util.Date;
@Component public class JwtUtil { private final SecretKey key; private final long expiration; public JwtUtil(@Value("${worksphere.jwt.secret}") String secret,@Value("${worksphere.jwt.expiration-ms}") long exp){key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));expiration=exp;} public String generateToken(String email){Date now=new Date();return Jwts.builder().subject(email).issuedAt(now).expiration(new Date(now.getTime()+expiration)).signWith(key).compact();} public String extractUsername(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject();} public boolean valid(String token,String email){try{return email.equals(extractUsername(token)) && !Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getExpiration().before(new Date());}catch(Exception e){return false;}} }
